import{_ as l,o as t,c as a,a4 as i}from"./chunks/framework.DzJZdBQK.js";const h=JSON.parse('{"title":"写作课作业-102","description":"","frontmatter":{"date":"2020-11-03T00:04:38","title":"写作课作业-102","categories":["写作","作业","一年顶十年"],"tags":["写作","作业","一年顶十年"]},"headers":[{"level":2,"title":"知识点","slug":"知识点","link":"#知识点","children":[]},{"level":2,"title":"我的思考","slug":"我的思考","link":"#我的思考","children":[]}],"relativePath":"posts/homework/102.md","filePath":"posts/homework/102.md"}'),o={name:"posts/homework/102.md"};function r(p,e,s,n,_,c){return t(),a("div",null,[...e[0]||(e[0]=[i('<blockquote><p>《一年顶十年》之《讲课 如何成为一名吸金的好老师？》</p></blockquote><h2 id="知识点" tabindex="-1">知识点 <a class="header-anchor" href="#知识点" aria-label="Permalink to &quot;知识点&quot;">​</a></h2><ul><li>一个拥有良好的讲课能力，意味着他能很好地把知识、道理、事情讲明白，让人愿意听、听得懂、有启发，且愿意去改变。</li><li>通过录制视频来训练自己的讲课能力——选一个话题，录制1～3分钟的即兴讲话视频。</li><li>你需要多听讲课高手的课，不仅要听，还要看他们的视频，不仅要看，还要模仿他们的语音语调，表情姿态。如果有机会，一定要去线下见他们，近距离聆听、观察、学习。</li><li>一个人要想真正在讲课这件事上有所突破，就一定要走到线下去，走到真实的场景中去讲课，面对真实的人，哪怕只有一个听众，也好过你自己一个人练习。</li><li>开课并不难，你也可以，真的。如果你从不开始，对不起，你永远成不了讲课高手。</li><li>高频思考，讲我所做，疯狂练习。</li><li>如何让自己更幽默：多听搞笑的内容；多背段子；改编段子并多讲；遇到好笑的事情整理成段子并讲出来；多跟幽默搞笑的人一起玩。</li><li>简单易懂、非常好用、充满力量，你的课肯定会更受欢迎。</li></ul><h2 id="我的思考" tabindex="-1">我的思考 <a class="header-anchor" href="#我的思考" aria-label="Permalink to &quot;我的思考&quot;">​</a></h2><p>把讲课当成是把事情说清楚的一个环节来锻炼，对于讲课的心理门槛就会降低下来。</p><p>根据不同的场合需要，改编段子，并多讲。如果一个段子都可以按这样的方式来练习，一个好的故事，一个好的案例，一次犯的错误也都可以在不同的场景里面去演化。</p><hr><p>欢迎联系我</p><p>微信号 ：Crazy_Airhead</p><p>Mixin ID : 1091586</p><p>定投课堂邀请码：6DYMBFP061</p><p>李笑来写作课邀请码：38MDGFYZK8</p><p>水龙头邀请码：FDJQHJ</p>',13)])])}const u=l(o,[["render",r]]);export{h as __pageData,u as default};
